// LEAD VALIDATOR - v4
// Validates required fields, phone (E.164) and email format.
// Outputs a clean lead object used by ALL downstream nodes.

const body = $input.first().json.body || {};

const required = ['name', 'phone', 'email', 'budget', 'location', 'property_type'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');
if (missing.length > 0) {
  throw new Error('Validation Failed - Missing required fields: ' + missing.join(', '));
}

const phone = String(body.phone).replace(/\s+/g, '');
if (!/^\+[1-9]\d{9,14}$/.test(phone)) {
  throw new Error('Invalid phone format. Use E.164 (e.g. +919876543210). Got: ' + phone);
}

const email = String(body.email).trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('Invalid email format: ' + body.email);
}

const propertyType = String(body.property_type).trim();
const message = String(body.message || '').trim();
const bhkMatch = (propertyType + ' ' + message).match(/(\d+(?:\.\d+)?)\s*-?\s*BHK/i);

return [{
  json: {
    name: String(body.name).trim(),
    phone,
    phone_digits: phone.replace(/\D/g, ''),   // WhatsApp ko sirf digits chahiye
    email,
    budget: String(body.budget).trim(),
    location: String(body.location).trim(),
    property_type: propertyType,
    bhk: bhkMatch ? bhkMatch[1] : '',
    purpose: String(body.purpose || 'Not specified').trim(),
    timeline: String(body.timeline || 'Not specified').trim(),
    message,
    source: String(body.source || 'Direct Enquiry').trim(),
    validated_at: new Date().toISOString()
  }
}];

// DUPLICATE REAL ESTATE LEAD CHECKER
// Checks whether the incoming phone number already exists
// in the Real Estate CRM Google Sheet.

// Get the current lead from the first Code node
const lead = $('Code in JavaScript3').first().json;

// Get incoming phone number
const phone = String(
  lead.phone || ''
).replace(/\D/g, '');

// Get all existing leads from Google Sheets
const allRows = $input.all();

let isDuplicate = false;
let existingInfo = null;

// Check every existing lead
for (const row of allRows) {

  // Phone Number column from Google Sheet
  const rowPhone = String(
    row.json['Phone Number'] || ''
  ).replace(/\D/g, '');

  // Compare phone numbers
  if (rowPhone === phone && phone !== '') {

    isDuplicate = true;

    existingInfo = {
      name: row.json['Lead Name'] || 'Unknown',
      email: row.json['Email'] || 'Unknown',
      status: row.json['Lead Status'] || 'Unknown',
      location: row.json['Location'] || 'Unknown',
      property_type: row.json['Property Type'] || 'Unknown',
      budget: row.json['Budget'] || 'Unknown',
      bhk: row.json['BHK'] || 'Unknown',
      purpose: row.json['Purpose'] || 'Unknown',
      timeline: row.json['Timeline'] || 'Unknown',
      created_at: row.json['Created At'] || 'Unknown'
    };

    break;
  }
}

// Return result
return [
  {
    json: {
      is_duplicate: isDuplicate,
      existing_info: existingInfo,
      phone: phone
    }
  }
];

