// CALENDAR CONFLICT CHECKER + FREE SLOT FINDER (IST)
// Tries tomorrow: 9 AM -> 5 PM (1-hour slots, ends by 6 PM)
// Fallback: day after tomorrow at 10 AM if all slots are taken

const events = $input.all().map(i => i.json).filter(e => e.start); // may be empty = no conflicts
const busy = events.map(e => ({
  start: new Date(e.start.dateTime || e.start.date),
  end: new Date(e.end.dateTime || e.end.date)
}));

const IST = 5.5 * 60 * 60 * 1000;
const nowIST = new Date(Date.now() + IST);

function makeSlot(dayOffset, hour) {
  const start = new Date(Date.UTC(
    nowIST.getUTCFullYear(),
    nowIST.getUTCMonth(),
    nowIST.getUTCDate() + dayOffset,
    hour, 0, 0
  ) - IST);
  const end = new Date(start.getTime() + 60 * 60000);
  return { start, end, hour };
}

function label(hour) {
  const h12 = hour % 12 || 12;
  return `${h12}:00 ${hour < 12 ? 'AM' : 'PM'}`;
}

function dateLabel(d) {
  return d.toLocaleDateString('en-IN', {
    timeZone: 'Asia/Kolkata',
    weekday: 'short', day: 'numeric', month: 'short', year: 'numeric'
  });
}

const hours = [9, 10, 11, 12, 13, 14, 15, 16, 17];
let chosen = null;
let fallback = false;

for (const h of hours) {
  const s = makeSlot(1, h);
  const clash = busy.some(b => s.start < b.end && s.end > b.start);
  if (!clash) { chosen = s; break; }
}

if (!chosen) {
  chosen = makeSlot(2, 10);
  fallback = true;
}

return [{
  json: {
    slot_start: chosen.start.toISOString(),
    slot_end: chosen.end.toISOString(),
    slot_time: label(chosen.hour),
    slot_date: dateLabel(chosen.start),
    slot_found: true,
    is_fallback: fallback,
    conflicts_found: busy.length,
    slot_hour: chosen.hour
  }
}];

